alter policy studio_objects_read on storage.objects using (bucket_id='companion-studio' and (exists(select 1 from public.studio_admins where user_id=(select auth.uid())) or exists(select 1 from public.studio_assets a where a.object_path=storage.objects.name and a.status='published'))); alter policy studio_objects_cleanup on storage.objects using (bucket_id='companion-studio' and exists(select 1 from public.studio_admins where user_id=(select auth.uid())) and not exists(select 1 from public.studio_assets a where a.object_path=storage.objects.name));